mapper.update:
UPDATE analyses
SET status = 'FAILED', error_code = #{errorCode}, error_message = #{errorMessage}, updated_at = #{now}
WHERE id = #{id} AND status NOT IN ('DONE', 'FAILED')

UPDATE analyses SET is_public = #{isPublic}, updated_at = #{now}
WHERE id = #{id} AND user_id = #{userId} AND deleted_at IS NULL
  AND (#{isPublic} = FALSE OR status = 'DONE')

UPDATE analyses
SET overview = #{overview, javaType=com.vibenote.analysis.explain.AnalysisOverview,
               typeHandler=com.vibenote.common.mybatis.JsonTypeHandler}
WHERE id = #{id}

UPDATE analyses
SET status = 'FAILED', error_code = #{errorCode}, error_message = #{errorMessage}, updated_at = #{now}
WHERE status NOT IN ('DONE', 'FAILED') AND deleted_at IS NULL
